import re,glob,os
files=glob.glob('internal/**/*.go',recursive=True)
decls=[]
for f in files:
 s=open(f).read()
 for m in re.finditer(r'^\s*func\s+(?:\([^\n]*?\)\s*)?([A-Za-z_]\w*)\s*\(',s,re.M): decls.append((m.group(1),f))
for n,f in decls:
 c=0
 for g in glob.glob('**/*.go',recursive=True):
  t=open(g,errors='ignore').read(); c+=len(re.findall(r'\b'+re.escape(n)+r'\s*\(',t))
 print(c-1,n,f)
PY",workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:20000}); text(r.output);

